PHRASES += [
    ("Ekran yardımı", "Screen help", "Hilfe zu dieser Ansicht"),
    ("Seçili ekin ve konum hakkında bir soru yaz. Enter gönderir. Yeni sohbet için ↻ düğmesine bas.", "Ask about the selected crop and location. Press Enter to send or ↻ to start a new chat.", "Stelle eine Frage zur gewählten Kultur und zum Standort. Enter sendet, ↻ startet einen neuen Chat."),
    ("Tarla panellerini, kaynakları, frekans denemesini veya Özelleştirme’yi aç.", "Open field panels, data sources, the frequency test, or customization.", "Öffne Feldansichten, Datenquellen, den Frequenztest oder die Anpassung."),
    ("Tema ve dili seç, asistan için API anahtarını ayarla veya ana ekran turunu başlat.", "Choose a theme and language, set the assistant API key, or restart the main-screen tour.", "Wähle Design und Sprache, richte den API-Schlüssel ein oder starte die Tour zur Hauptansicht."),
    ("Kayıtlı bir tarlayı analiz et, haritada aç veya sil. Yeni bir sınır çizerek tarla ekleyebilirsin.", "Analyze, open on the map, or delete a saved field. Draw a boundary to add a new field.", "Analysiere ein gespeichertes Feld, öffne es auf der Karte oder lösche es. Zeichne eine Grenze, um ein Feld hinzuzufügen."),
    ("Dönemi ve girdi miktarlarını yaz. Hesapla düğmesi yararlı kullanım ve kayıp tahminini gösterir.", "Enter the period and amounts. Calculate shows estimated useful use and losses.", "Gib Zeitraum und Mengen ein. Die Berechnung zeigt geschätzte Nutzung und Verluste."),
    ("Mevcut ekinlerini ve önceliğini seç. Öneri bul’a bas, sonra diğer rotasyon kartlarına tıklayarak sonuçları karşılaştır.", "Select your current crops and priority. Find a recommendation and click the other rotation cards to compare.", "Wähle deine aktuellen Kulturen und Priorität. Suche eine Empfehlung und klicke auf andere Fruchtfolgen zum Vergleich."),
    ("Yıllara göre ekin uygunluğu ve su açığını karşılaştır. Tarla geçmişinden önceki ekimleri görebilirsin.", "Compare crop suitability and water deficit across years. Open field history to see past crops.", "Vergleiche Kultureignung und Wasserdefizit über mehrere Jahre. Frühere Kulturen stehen in der Feldhistorie."),
    ("Yıllık iklimi ve kaydettiğin ekimleri incele. Ürün adını ve yılı seçerek ekim kaydı ekle.", "Review annual climate and saved crops. Select a crop and year to add a record.", "Prüfe Jahresklima und gespeicherte Kulturen. Wähle Kultur und Jahr für einen neuen Eintrag."),
    ("Afet ve erozyon göstergelerini incele. Haşere riski sekmesinde ürün seçerek bölgesel kayıtları sorgula.", "Review disaster and erosion indicators. Select a crop under Pest risk to query regional records.", "Prüfe Naturgefahren und Erosion. Wähle unter Schädlingsrisiko eine Kultur für regionale Nachweise."),
    ("Ekim sıralarını su, toprak sağlığı ve çeşitlilik puanlarına göre karşılaştır.", "Compare crop sequences by water, soil health, and diversity scores.", "Vergleiche Anbaufolgen anhand von Wasser, Bodengesundheit und Vielfalt."),
    ("Özet, kaynakça ve hesap yöntemi sekmelerinden verilerin nasıl kullanıldığını incele.", "Use the summary, references, and calculation tabs to see how the data are used.", "Unter Übersicht, Quellen und Berechnung siehst du, wie die Daten verwendet werden."),
    ("Deneme tonunu seç. Arduino bağlantısını kurduktan sonra Protokolü çal ve Durdur düğmelerini kullan.", "Select a test tone. Connect Arduino, then use Play protocol and Stop.", "Wähle einen Testton. Verbinde Arduino und nutze anschließend Protokoll abspielen und Stopp."),
    ("Parsel göstergelerini ve rotasyonların toprak, su ve azot üzerindeki etkilerini karşılaştır.", "Compare parcel indicators and how rotations affect soil, water, and nitrogen.", "Vergleiche Parzellenindikatoren und Auswirkungen der Fruchtfolgen auf Boden, Wasser und Stickstoff."),
    ("Haritada tarlanın köşelerini sırayla işaretle. Sınırı analiz için kullanabilir veya Tarlalarım’a kaydedebilirsin.", "Mark the field corners in order. Use the boundary for analysis or save it in My fields.", "Markiere die Feldecken der Reihe nach. Nutze die Grenze zur Analyse oder speichere sie unter Meine Felder."),
    ("Uydu haritasındaki katman düğmeleriyle parsel göstergelerini ve ısı haritasını incele.", "Use the satellite map layer buttons to inspect parcel indicators and the heat map.", "Nutze die Ebenenschaltflächen der Satellitenkarte für Parzellenindikatoren und die Heatmap."),
    ("Toprak organik karbonunun dağılımını renk ölçeğiyle incele. Kaydırıcı kaplamanın görünürlüğünü ayarlar.", "Use the color scale to inspect soil organic carbon. The slider controls overlay opacity.", "Nutze die Farbskala für organischen Bodenkohlenstoff. Der Regler steuert die Deckkraft."),
    ("GPS’i veya simülasyonu aç. Parseller arasında ilerlerken ekin önerilerini sesli dinle.", "Enable GPS or simulation to hear crop recommendations as you move between parcels.", "Aktiviere GPS oder Simulation, um beim Wechsel zwischen Parzellen Anbauempfehlungen zu hören."),
    ("Planla, İzle ve Ayarlar’a tıklayarak ilgili araçları aç.", "Click Plan, Monitor, or Settings to open the related tools.", "Klicke auf Planen, Beobachten oder Einstellungen, um die Werkzeuge zu öffnen."),
]


