def _build(code):
    col = 1 if code == "en" else 2
    table = {p[0]: p[col] for p in PHRASES}
    parts = []
    for src in sorted(table, key=len, reverse=True):
        pre = r"(?<!\w)" if src[0].isalnum() else ""
        post = r"(?!\w)" if src[-1].isalnum() else ""
        parts.append(pre + re.escape(src) + post)
    _tables[code] = (table, re.compile("|".join(parts)))


def set_lang(code):
    LANG["code"] = code if code in LANG_NAMES else "tr"
    _cache.clear()


def lang():
    return LANG["code"]


def tr(text):
    """Metni seçili dile çevir (bilinmeyen kısımlar olduğu gibi kalır)."""
    code = LANG["code"]
    if code == "tr" or not isinstance(text, str) or isinstance(text, NoTr) or not text:
        return text
    if not _alpha.search(text):
        return text
    hit = _cache.get(text)
    if hit is not None:
        return hit
    if code not in _tables:
        _build(code)
    table, rx = _tables[code]
    if text in table:
        return table[text]
    out = re.sub(r"(?<!\w)Ekim:? (%s)(?!\w)" % _MONTHS_TR,
                 lambda m: _SOW[code] + ": " + m.group(1), text)
    out = rx.sub(lambda m: table[m.group(0)], out)
    if len(_cache) > 6000:
        _cache.clear()
    _cache[text] = out
    return out


def install(tk):
    """tkinter'ın metin gösteren noktalarını sar. Bir kez çağrılır."""
    if getattr(tk, "_tarla_dil", False):
        return
    tk._tarla_dil = True

    def wrap_kw(kw):
        if "text" in kw:
            kw["text"] = tr(kw["text"])
        return kw

    try:
        _install(tk, wrap_kw)
    except AttributeError:          # beklenmeyen tkinter sürümü: çeviri olmadan devam
        pass


def _install(tk, wrap_kw):
    canvas_create_text = tk.Canvas.create_text
    tk.Canvas.create_text = lambda self, *a, **kw: canvas_create_text(self, *a, **wrap_kw(kw))
    canvas_itemconfigure = tk.Canvas.itemconfigure

    def itemconfigure(self, tag, cnf=None, **kw):
        return canvas_itemconfigure(self, tag, cnf, **wrap_kw(kw))
    tk.Canvas.itemconfigure = tk.Canvas.itemconfig = itemconfigure

    for cls in (tk.Label, tk.Button):
        init, conf = cls.__init__, cls.configure

        def new_init(self, master=None, cnf={}, _init=init, **kw):
            _init(self, master, cnf, **wrap_kw(kw))

        def new_conf(self, cnf=None, _conf=conf, **kw):
            return _conf(self, cnf, **wrap_kw(kw))
        cls.__init__ = new_init
        cls.configure = cls.config = new_conf

    wm_title = tk.Wm.wm_title

    def title(self, string=None):
        return wm_title(self, tr(string) if string is not None else None)
    tk.Wm.wm_title = tk.Wm.title = title


