for _i in range(12):
    _t, _e, _d = _MON[0][_i], _MON[1][_i], _MON[2][_i]
    _WEB += [(f"Toprak nemi {_t} ayında kritik eşiğe iniyor.", f"Soil moisture drops to a critical level in {_e}.", f"Die Bodenfeuchte erreicht im {_d} einen kritischen Wert."),
             (f"{_t} ayında ısı stresi yüksek.", f"Heat stress is high in {_e}.", f"Im {_d} ist der Hitzestress hoch.")]
